    c.fillStyle = '#b08848'; c.fillRect(1, 2, 14, 12);
    c.fillStyle = '#d0a868'; c.fillRect(2, 3, 12, 9);
  });
  tile('void', c => { c.fillStyle = '#101018'; c.fillRect(0, 0, 16, 16); });

  // ---- Character sprites ---------------------------------------------------
  // 16x16 string art. Palette keys: H hair, S skin, T shirt, P pants, W white, K black(outline)
  const HERO_DOWN_STAND = [
    '................',
    '.....HHHHHH.....',
    '....HHHHHHHH....',
    '...HHHHHHHHHH...',
    '...HHSSSSSSHH...',
    '...HSSKSSKSSH...',
