  const HERO_UP_STAND = HERO_DOWN_STAND.map(r => r.replace(/K/g, 'H')).map((r, i) =>
    i === 5 ? r.replace(/S/g, 'H') : i === 4 ? r.replace(/S/g, 'H') : r);
  const HERO_UP_WALK = HERO_DOWN_WALK.map(r => r.replace(/K/g, 'H')).map((r, i) =>
    i === 5 ? r.replace(/S/g, 'H') : i === 4 ? r.replace(/S/g, 'H') : r);
  const HERO_LEFT_STAND = [
    '................',
    '.....HHHHHH.....',
    '....HHHHHHHH....',
    '...HHHHHHHHHH...',
    '...HSSSSSSHH....',
    '...HSKSSSHHH....',
