  function paintSprite(rows, pal, flip) {
    const c = makeCanvas(16, 16);
    const ctx = c.getContext('2d');
    for (let y = 0; y < 16; y++) {
      for (let x = 0; x < 16; x++) {
        const ch = rows[y][flip ? 15 - x : x];
        if (ch !== '.' && pal[ch]) px(ctx, x, y, pal[ch]);
      }
    }
    return c;
  }

  // Build a character sheet: {down:[stand,walkA,walkB], up:[...], left:[...], right:[...]}
  function makeCharSheet(pal) {
    const mk = (rows, flip) => paintSprite(rows, pal, flip);
    const downW = mk(HERO_DOWN_WALK), upW = mk(HERO_UP_WALK);
    return {
      down: [mk(HERO_DOWN_STAND), downW, downW],
      up: [mk(HERO_UP_STAND), upW, upW],
      left: [mk(HERO_LEFT_STAND), mk(HERO_LEFT_WALK)],
      right: [mk(HERO_LEFT_STAND, true), mk(HERO_LEFT_WALK, true)],
    };
  }

  const PALETTES = {
    hero:   { H: '#c83830', S: '#f8c898', T: '#3858c8', P: '#283048', W: '#f8f8f8', K: '#202020' },
    rival:  { H: '#8a5a30', S: '#f8c898', T: '#5848a8', P: '#383838', W: '#f8f8f8', K: '#202020' },
    oak:    { H: '#d8d8d8', S: '#f0c090', T: '#e8e8e8', P: '#705838', W: '#f8f8f8', K: '#202020' },
    mom:    { H: '#a85828', S: '#f8c898', T: '#e87898', P: '#c85878', W: '#f8f8f8', K: '#202020' },
    nurse:  { H: '#e87898', S: '#f8c898', T: '#f8f8f8', P: '#f8b8c8', W: '#f8f8f8', K: '#202020' },
    clerk:  { H: '#3838a8', S: '#f8c898', T: '#3888c8', P: '#283048', W: '#f8f8f8', K: '#202020' },
    bug:    { H: '#c8a838', S: '#f8c898', T: '#d8d848', P: '#787838', W: '#f8f8f8', K: '#202020' },
    lass:   { H: '#c87828', S: '#f8c898', T: '#e85858', P: '#3858c8', W: '#f8f8f8', K: '#202020' },
    brock:  { H: '#583828', S: '#c88858', T: '#b86828', P: '#584838', W: '#f8f8f8', K: '#202020' },
    boy:    { H: '#383838', S: '#f8c898', T: '#48a858', P: '#484848', W: '#f8f8f8', K: '#202020' },
  };
  const SHEETS = {};
  for (const [k, p] of Object.entries(PALETTES)) SHEETS[k] = makeCharSheet(p);

  // ---- 5x7 bitmap font (all-caps, Gen-1 style) ----------------------------
  const GLYPHS = {
    A: '0E,11,11,1F,11,11,11', B: '1E,11,11,1E,11,11,1E', C: '0E,11,10,10,10,11,0E',
    D: '1E,11,11,11,11,11,1E', E: '1F,10,10,1E,10,10,1F', F: '1F,10,10,1E,10,10,10',
    G: '0E,11,10,17,11,11,0F', H: '11,11,11,1F,11,11,11', I: '0E,04,04,04,04,04,0E',
    J: '07,02,02,02,02,12,0C', K: '11,12,14,18,14,12,11', L: '10,10,10,10,10,10,1F',
    M: '11,1B,15,15,11,11,11', N: '11,19,15,13,11,11,11', O: '0E,11,11,11,11,11,0E',
    P: '1E,11,11,1E,10,10,10', Q: '0E,11,11,11,15,12,0D', R: '1E,11,11,1E,14,12,11',
    S: '0F,10,10,0E,01,01,1E', T: '1F,04,04,04,04,04,04', U: '11,11,11,11,11,11,0E',
    V: '11,11,11,11,11,0A,04', W: '11,11,11,15,15,1B,11', X: '11,11,0A,04,0A,11,11',
    Y: '11,11,0A,04,04,04,04', Z: '1F,01,02,04,08,10,1F',
    '0': '0E,11,13,15,19,11,0E', '1': '04,0C,04,04,04,04,0E', '2': '0E,11,01,06,08,10,1F',
    '3': '1F,01,02,06,01,11,0E', '4': '02,06,0A,12,1F,02,02', '5': '1F,10,1E,01,01,11,0E',
    '6': '06,08,10,1E,11,11,0E', '7': '1F,01,02,04,08,08,08', '8': '0E,11,11,0E,11,11,0E',
    '9': '0E,11,11,0F,01,02,0C',
    ' ': '00,00,00,00,00,00,00', '.': '00,00,00,00,00,0C,0C', ',': '00,00,00,00,0C,04,08',
    '!': '04,04,04,04,04,00,04', '?': '0E,11,01,02,04,00,04', "'": '04,04,08,00,00,00,00',
    '-': '00,00,00,1F,00,00,00', ':': '00,0C,0C,00,0C,0C,00', '/': '01,01,02,04,08,10,10',
    '(': '02,04,08,08,08,04,02', ')': '08,04,02,02,02,04,08', '…': '00,00,00,00,00,00,15',
    '♂': '07,03,05,08,14,14,08', '♀': '0E,11,11,0E,04,0E,04', '$': '04,0F,14,0E,05,1E,04',
    '%': '19,1A,02,04,08,0B,13', '+': '00,04,04,1F,04,04,00', '>': '08,04,02,01,02,04,08',
    '*': '00,0A,04,1F,04,0A,00', '"': '0A,0A,00,00,00,00,00', ';': '00,0C,0C,00,0C,04,08',
    'é': '0E,11,1F,10,11,0E,02',
  };
  const FONT = {};
  for (const [ch, rows] of Object.entries(GLYPHS)) {
    const c = makeCanvas(5, 7);
    const ctx = c.getContext('2d');
    rows.split(',').forEach((hex, y) => {
      const bits = parseInt(hex, 16);
      for (let x = 0; x < 5; x++) if (bits & (1 << (4 - x))) px(ctx, x, y, '#fff');
    });
    FONT[ch] = c;
  }
  const fontCache = {}; // color -> {ch -> tinted canvas}
  function glyph(ch, color) {
    const up = FONT[ch] ? ch : FONT[ch.toUpperCase()] ? ch.toUpperCase() : '?';
    fontCache[color] ??= {};
    if (!fontCache[color][up]) {
      const c = makeCanvas(5, 7);
      const ctx = c.getContext('2d');
      ctx.drawImage(FONT[up], 0, 0);
      ctx.globalCompositeOperation = 'source-in';
      ctx.fillStyle = color; ctx.fillRect(0, 0, 5, 7);
      fontCache[color][up] = c;
    }
    return fontCache[color][up];
  }

  function text(ctx, str, x, y, color = '#383838') {
    let cx = x;
    for (const ch of String(str)) {
      if (ch === '\n') { y += 9; cx = x; continue; }
      ctx.drawImage(glyph(ch, color), cx, y);
      cx += 6;
    }
    return cx;
  }
  const textWidth = (str) => String(str).length * 6;

  // ---- Pokémon sprite cache ------------------------------------------------
  const monImgs = {};
  function monSprite(id, side) { // side: 'front' | 'back'
    const key = side + id;
    if (!monImgs[key]) {
      const img = new Image();
      img.src = `assets/sprites/${side}/${id}.png`;
      monImgs[key] = img;
    }
    return monImgs[key];
  }
  function preloadAll() {
    for (let i = 1; i <= 151; i++) { monSprite(i, 'front'); monSprite(i, 'back'); }
  }

  // ---- UI chrome -----------------------------------------------------------
  function frame(ctx, x, y, w, h) { // FRLG-style dialog frame
    ctx.fillStyle = '#f8f8f8'; ctx.fillRect(x, y, w, h);
    ctx.fillStyle = '#58585f';
    ctx.fillRect(x, y, w, 2); ctx.fillRect(x, y + h - 2, w, 2);
    ctx.fillRect(x, y, 2, h); ctx.fillRect(x + w - 2, y, 2, h);
    ctx.fillStyle = '#b8c0c8';
    ctx.fillRect(x + 2, y + 2, w - 4, 1); ctx.fillRect(x + 2, y + h - 3, w - 4, 1);
    ctx.fillRect(x + 2, y + 2, 1, h - 4); ctx.fillRect(x + w - 3, y + 2, 1, h - 4);
  }

  function hpBar(ctx, x, y, w, cur, max) {
    ctx.fillStyle = '#58585f'; ctx.fillRect(x - 1, y - 1, w + 2, 5);
    ctx.fillStyle = '#404048'; ctx.fillRect(x, y, w, 3);
    const r = Math.max(0, cur / max);
    const col = r > 0.5 ? '#58d058' : r > 0.2 ? '#f8b838' : '#f05848';
    ctx.fillStyle = col;
    ctx.fillRect(x, y, Math.max(cur > 0 ? 1 : 0, Math.round(w * r)), 3);
  }

  return { TILE, T, SHEETS, text, textWidth, monSprite, preloadAll, frame, hpBar, makeCanvas };
})();
